/**
 * Process bootstrap.
 *
 * The middleware order here is load-bearing (ADR 0007): Better Auth's handler is
 * registered on the raw Express server *before* any body parser runs, because it
 * owns its own request parsing. Nest is created with `bodyParser: false` and the
 * parsers are added by hand afterwards, so the order is stated in one place
 * instead of depending on when Nest decides to install its own.
 */

import 'reflect-metadata';
import express from 'express';
import helmet from 'helmet';
import { NestFactory } from '@nestjs/core';
import { ExpressAdapter } from '@nestjs/platform-express';
import { AppModule } from './app.module.js';
import { DomainExceptionFilter } from './common/domain-exception.filter.js';
import { loadEnv } from './config/env.js';
import { getAuth } from './identity/auth/better-auth.provider.js';
import { PrismaService } from './prisma/prisma.service.js';

/** A document body is small; anything larger is a bug or an attack. */
const BODY_LIMIT = '1mb';

async function bootstrap(): Promise<void> {
  const env = loadEnv();
  const server = express();

  const app = await NestFactory.create(AppModule, new ExpressAdapter(server), {
    bodyParser: false,
    bufferLogs: true,
  });

  // 1. Security headers first, so even an auth failure is not a bare response.
  app.use(
    helmet({
      // The API serves JSON and PDFs, never HTML, so a restrictive policy costs
      // nothing and removes an entire class of injection surface.
      contentSecurityPolicy: { directives: { defaultSrc: ["'none'"], frameAncestors: ["'none'"] } },
      referrerPolicy: { policy: 'no-referrer' },
    }),
  );

  // 2. Better Auth, before any body parser: it parses its own requests.
  const auth = await getAuth(app.get(PrismaService));
  server.use('/api/auth', auth.nodeHandler);

  // 3. Body parsing, for everything else.
  app.use(express.json({ limit: BODY_LIMIT }));
  app.use(express.urlencoded({ extended: true, limit: BODY_LIMIT }));

  // Exact origins only. A wildcard alongside credentials is an open door.
  app.enableCors({
    origin: env.CORS_ORIGINS,
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'DELETE'],
  });
  app.useGlobalFilters(new DomainExceptionFilter());
  app.enableShutdownHooks();

  // Everything Nest serves lives under `/api`, so the API, Better Auth at
  // `/api/auth`, and the Caddy rule `handle /api/*` all address one path space.
  // Without this, health answered at `/health` while every caller — the browser,
  // the container healthcheck, the deploy script — asked for `/api/...`.
  app.setGlobalPrefix('api');

  await app.init();

  server.listen(env.API_PORT, env.API_HOST, () => {
    process.stdout.write(`easyERP api listening on ${env.API_HOST}:${env.API_PORT}\n`);
  });
}

bootstrap().catch((error: unknown) => {
  process.stderr.write(
    `easyERP api failed to start: ${error instanceof Error ? error.stack : String(error)}\n`,
  );
  process.exitCode = 1;
});

/**
 * Vercel Serverless entry point for the API.
 *
 * The production VPS uses `main.ts` with native Node + systemd.
 * Vercel serverless functions need a different bootstrap:
 * - No persistent process, so no `onModuleInit` at startup
 * - Better Auth handler must be mounted before body parsing
 * - Each invocation is a cold start (or warm), so Prisma connection pooling is critical
 */

import 'reflect-metadata';
import express from 'express';
import helmet from 'helmet';
import { NestFactory } from '@nestjs/core';
import { ExpressAdapter } from '@nestjs/platform-express';
import { AppModule } from './app.module.js';
import { DomainExceptionFilter } from './common/domain-exception.filter.js';
import { loadEnv } from './config/env.js';
import { getAuth } from './identity/auth/better-auth.provider.js';
import { PrismaService } from './prisma/prisma.service.js';

/** A document body is small; anything larger is a bug or an attack. */
const BODY_LIMIT = '1mb';

let cachedApp: ReturnType<typeof express> | null = null;

export async function createServerlessApp(): Promise<express.Express> {
  if (cachedApp) return cachedApp;

  const env = loadEnv();
  const server = express();

  const app = await NestFactory.create(AppModule, new ExpressAdapter(server), {
    bodyParser: false,
    bufferLogs: true,
    logger: false,
  });

  // Security headers
  app.use(
    helmet({
      contentSecurityPolicy: { directives: { defaultSrc: ["'none'"], frameAncestors: ["'none'"] } },
      referrerPolicy: { policy: 'no-referrer' },
    }),
  );

  // Better Auth BEFORE body parsing (ADR 0007)
  const auth = await getAuth(app.get(PrismaService));
  server.use('/api/auth', auth.nodeHandler);

  // Body parsing for everything else
  app.use(express.json({ limit: BODY_LIMIT }));
  app.use(express.urlencoded({ extended: true, limit: BODY_LIMIT }));

  app.enableCors({
    origin: env.CORS_ORIGINS,
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'DELETE'],
  });
  app.useGlobalFilters(new DomainExceptionFilter());
  app.setGlobalPrefix('api');

  await app.init();

  cachedApp = server;
  return server;
}

// Vercel expects a default export of the Express app
export default async function handler(req: express.Request, res: express.Response) {
  const app = await createServerlessApp();
  return app(req, res);
}

/**
 * The process environment, parsed once at startup. A missing or malformed
 * variable stops the process before it accepts traffic, because a rollout that
 * starts with an unset secret is a rollout that serves a broken Business.
 */

import { z } from 'zod';

const schema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  API_PORT: z.coerce.number().int().min(1).max(65_535).default(3002),
  API_HOST: z.string().min(1).default('0.0.0.0'),
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),

  DATABASE_URL: z.string().min(1, 'DATABASE_URL is required'),
  DATABASE_POOL_MAX: z.coerce.number().int().min(1).max(200).default(10),

  /**
   * Where archived PDFs are written (ADR 0010).
   *
   * Required in production and defaulted only for local use, because the failure
   * mode of getting this wrong is not a crash: documents issue fine and the copy a
   * client is entitled to cannot be produced later.
   */
  DOCUMENT_ARCHIVE_ROOT: z.string().min(1).default('var/documents'),

  /**
   * The token that opens first-run Setup (ADR 0012). Read from the host's own
   * environment. Defaulted only for local use, because a fresh checkout should
   * `pnpm dev` into a working Setup without inventing a secret.
   */
  FIRST_SETUP_TOKEN: z.string().min(8).default('dev-first-setup-token'),

  BETTER_AUTH_SECRET: z.string().min(32, 'BETTER_AUTH_SECRET must be at least 32 characters'),
  BETTER_AUTH_URL: z.url(),
  CORS_ORIGINS: z
    .string()
    .min(1)
    .transform((value) =>
      value
        .split(',')
        .map((origin) => origin.trim())
        .filter(Boolean),
    )
    .refine((origins) => origins.every((origin) => !origin.includes('*')), {
      message:
        'CORS_ORIGINS accepts exact origins, never a wildcard: a wildcard plus credentials is a credentialed open door',
    }),
});

export type Env = z.infer<typeof schema> & { readonly isProduction: boolean };

let cached: Env | undefined;

export function loadEnv(source: NodeJS.ProcessEnv = process.env): Env {
  const parsed = schema.safeParse(source);
  if (!parsed.success) {
    const detail = parsed.error.issues
      .map((issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`)
      .join('; ');
    throw new Error(`Invalid environment: ${detail}`);
  }
  if (
    parsed.data.NODE_ENV === 'production' &&
    parsed.data.DOCUMENT_ARCHIVE_ROOT === 'var/documents'
  ) {
    // The default is a development convenience; accepting it in production would let
    // a rollout start with a relative path that resolves against whatever the
    // working directory happened to be, and every issued document would be
    // unretrievable after the next deploy.
    throw new Error('DOCUMENT_ARCHIVE_ROOT must be set to an absolute path in production');
  }
  if (
    parsed.data.NODE_ENV === 'production' &&
    parsed.data.FIRST_SETUP_TOKEN === 'dev-first-setup-token'
  ) {
    // The default is a development convenience. Accepting it in production means a
    // rollout that omits the token silently ships with a Setup gate anyone can
    // guess, which is the exact door ADR 0012 exists to close.
    throw new Error('FIRST_SETUP_TOKEN must be set to a non-default value in production');
  }

  return Object.freeze({ ...parsed.data, isProduction: parsed.data.NODE_ENV === 'production' });
}

/** The parsed environment for the running process. Call after `loadEnv`. */
export function env(): Env {
  cached ??= loadEnv();
  return cached;
}

/** Replace the cached environment. Tests use this to inject a known environment. */
export function setEnv(next: Env | undefined): void {
  cached = next;
}
